const SECTOR_SIZE = 4096;
const TERMINATOR = 0xFF;
const TEMPLATE_SAVE_B64 = "";

// clamp and trim ID input values
function setupIDInput(elementId) {
    const el = document.getElementById(elementId);
    el.addEventListener('input', function () {
        if (this.value.length > 5) {
            this.value = this.value.slice(0, 5);
        }
    });
    el.addEventListener('blur', function () {
        let val = parseInt(this.value);
        if (!isNaN(val)) {
            if (val < 0) this.value = 0;
            if (val > 65535) this.value = 65535;
        }
    });
}

setupIDInput('tid');
setupIDInput('sid');

// convert Base64 string into an ArrayBuffer
function base64ToArrayBuffer(base64) {
    const binaryString = window.atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
}

// create a reverse map to turn hex bytes back into characters
const reverseCharMap = {};
for (const [char, hex] of Object.entries(charMap)) {
    reverseCharMap[hex] = char;
}

// find active save slot's sector 0 (keeps backwards compatibility for loading info)
function getActiveSector0Offset(dataView) {
    let latestSector0Offset = -1;
    let maxSaveIndex = -1;

    for (let i = 0; i < 28; i++) { // 14 sectors * 2 save slots
        const offset = i * SECTOR_SIZE;
        const sectorId = dataView.getUint16(offset + 0x0FF4, true);
        const saveIndex = dataView.getUint32(offset + 0x0FF8, true);

        if (sectorId === 0 && saveIndex > maxSaveIndex) {
            maxSaveIndex = saveIndex;
            latestSector0Offset = offset;
        }
    }

    if (latestSector0Offset === -1) throw new Error("Invalid save file structure: Sector 0 missing.");
    return latestSector0Offset;
}

// find ALL sector 0 offsets across both save slots
function getAllSector0Offsets(dataView) {
    let offsets = [];
    for (let i = 0; i < 28; i++) { // 14 sectors * 2 save slots
        const offset = i * SECTOR_SIZE;
        const sectorId = dataView.getUint16(offset + 0x0FF4, true);
        if (sectorId === 0) {
            offsets.push(offset);
        }
    }
    if (offsets.length === 0) throw new Error("Invalid save file structure: No Sector 0 found.");
    return offsets;
}

// validate and/or generate ID
function validateID(elementId, label) {
    const el = document.getElementById(elementId);
    let val = parseInt(el.value);
    if (isNaN(val)) {
        val = Math.floor(Math.random() * 65536);
        el.value = val;
    } else if (val < 0 || val > 65535) {
        throw new Error(`${label} must be between 0 and 65535.`);
    }
    return val;
}

// convert standard ASCII alphanumeric characters to fullwidth characters
function toFullwidth(str) {
    return str.replace(/[A-Za-z0-9]/g, function (char) {
        return String.fromCharCode(char.charCodeAt(0) + 0xFEE0);
    });
}

// ensure every character exists in the GBA charMap
function sanitizeTrainerName(rawName) {
    const convertedName = toFullwidth(rawName);
    let cleanName = "";

    for (let i = 0; i < convertedName.length; i++) {
        if (charMap[convertedName[i]] !== undefined) {
            cleanName += convertedName[i];
        }
    }
    return cleanName.substring(0, 5);
}

// calculate checksum
function calculateChecksum(dataView, offset) {
    let sum = 0;
    for (let i = 0; i < 0x0F80; i += 4) {
        sum += dataView.getUint32(offset + i, true);
    }
    return ((sum & 0xFFFF) + (sum >>> 16)) & 0xFFFF;
}

function randomizeIDs() {
    // Emerald uses a 32-bit LCG: seed = (seed * 0x41C64E6D + 0x6073)
    let seed = Math.floor(Math.random() * 0xFFFFFFFF);

    // simulate title screen frame delay
    let frames = Math.floor(Math.random() * 5000) + 1000;
    for (let i = 0; i < frames; i++) {
        seed = (Math.imul(seed, 0x41C64E6D) + 0x6073) >>> 0;
    }

    // two RNG calls: TID then SID, take top 16 bits
    seed = (Math.imul(seed, 0x41C64E6D) + 0x6073) >>> 0;
    const tid = seed >>> 16;

    seed = (Math.imul(seed, 0x41C64E6D) + 0x6073) >>> 0;
    const sid = seed >>> 16;

    document.getElementById('tid').value = tid;
    document.getElementById('sid').value = sid;
}

function setStatus(msg, isError = false) {
    const el = document.getElementById('status');
    el.textContent = msg;
    el.className = isError ? 'error' : 'success';
}

// file parsing
document.getElementById('user-save-file').addEventListener('change', function (event) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function (e) {
        try {
            const dataView = new DataView(e.target.result);
            const latestSector0Offset = getActiveSector0Offset(dataView);

            const gender = dataView.getUint8(latestSector0Offset + 0x0008);
            const tid = dataView.getUint16(latestSector0Offset + 0x000A, true);
            const sid = dataView.getUint16(latestSector0Offset + 0x000C, true);

            let name = "";
            for (let i = 0; i < 8; i++) {
                const charHex = dataView.getUint8(latestSector0Offset + i);
                if (charHex === TERMINATOR) break;
                if (reverseCharMap[charHex]) name += reverseCharMap[charHex];
            }

            document.getElementById('trainer-name').value = name;
            if (gender === 1) {
                document.getElementById('gender-girl').checked = true;
            } else {
                document.getElementById('gender-boy').checked = true;
            }
            document.getElementById('tid').value = tid;
            document.getElementById('sid').value = sid;

            setStatus("Loaded trainer info from save!");
        } catch (error) {
            console.error(error);
            setStatus("Failed to read save: " + error.message, true);
        }

        event.target.value = '';
    };

    reader.readAsArrayBuffer(file);
});

async function generateSave() {
    try {
        const rawName = document.getElementById('trainer-name').value;
        const name = sanitizeTrainerName(rawName);

        if (name.length === 0) {
            throw new Error("Trainer name contains no valid characters.");
        }

        const tid = validateID('tid', 'TID');
        const sid = validateID('sid', 'SID');
        const gender = parseInt(document.querySelector('input[name="gender"]:checked').value);

        setStatus("Processing...");

        const buffer = base64ToArrayBuffer(TEMPLATE_SAVE_B64);
        const dataView = new DataView(buffer);

        // get all sector 0 offsets
        const sector0Offsets = getAllSector0Offsets(dataView);

        // overwrite both slots of the save file
        for (const sectorOffset of sector0Offsets) {
            // set gender, TID, and SID
            dataView.setUint8(sectorOffset + 0x0008, gender);
            dataView.setUint16(sectorOffset + 0x000A, tid, true);
            dataView.setUint16(sectorOffset + 0x000C, sid, true);

            // set trainer name
            for (let i = 0; i < 8; i++) {
                const byteVal = i < name.length ? charMap[name[i]] : (i === name.length ? TERMINATOR : 0x00);
                dataView.setUint8(sectorOffset + i, byteVal);
            }

            // recalculate checksum for this half
            const checksum = calculateChecksum(dataView, sectorOffset);
            dataView.setUint16(sectorOffset + 0x0FF6, checksum, true);
        }

        // trigger download
        const blob = new Blob([buffer], { type: "application/octet-stream" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = "OSM_Emerald_J.sav";
        a.click();
        URL.revokeObjectURL(url);

        setStatus("Save generated!");

    } catch (error) {
        console.error(error);
        setStatus(error.message, true);
    }
}